CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_vehicle
COMMENT 'Vehicles on motor contracts; the insured object of the Risk. Grain: One row per vehicle on a contract. Conformed from PAS_MOTOR (lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_vehicle) by mapping pas_motor; column names and definitions are the core concept vehicle. Owner Head of Motor Underwriting; certified.'
AS
SELECT
  concat('PAS_MOTOR:', contract_reference, ':', vehicle_seq) AS vehicle_id,
  concat('PAS_MOTOR:', contract_reference, ':', vehicle_seq) AS insured_object_id,
  concat('PAS_MOTOR:', contract_reference) AS policy_id,
  reg_mark AS registration_number,
  make AS make,
  model AS model,
  year_of_manufacture AS year_of_manufacture,
  abi_group AS vehicle_group,
  vehicle_value_amt AS vehicle_value_amount
