COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_vehicle.policy_id IS 'Policy the object is insured under.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_vehicle.registration_number IS 'Vehicle registration mark. The policy system says ''reg mark''.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_vehicle.make IS 'Manufacturer.';

