CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage
COMMENT 'The policy system stores one cover code per contract (COMP, TPFT, TPO). The core models coverages as rows: every contract carries MOTOR_TPL; COMP and TPFT also carry MOTOR_OWN_DAMAGE. The conformed view explodes accordingly. Grain: One row per contract per coverage (two rows for comprehensive cover). Conformed from PAS_MOTOR (lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_cover) by mapping pas_motor; column names and definitions are the core concept coverage. Owner Head of Motor Underwriting; certified.'
AS
SELECT concat('PAS_MOTOR:', contract_reference, ':TPL') AS coverage_id,
       concat('PAS_MOTOR:', contract_reference) AS policy_id,
       'MOTOR_TPL' AS coverage_type_code,
       tpl_limit_amt AS limit_amount,
       CAST(NULL AS DECIMAL(18,2)) AS deductible_amount,
       CAST(NULL AS DECIMAL(18,2)) AS sum_insured_amount,
       cover_cd AS cover_code
FROM lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_cover
UNION ALL
SELECT concat('PAS_MOTOR:', contract_reference, ':OD'),
       concat('PAS_MOTOR:', contract_reference),
       'MOTOR_OWN_DAMAGE', CAST(NULL AS DECIMAL(18,2)), excess_amt, CAST(NULL AS DECIMAL(18,2)), cover_cd
FROM lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_cover
WHERE cover_cd IN ('COMP', 'TPFT');

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.coverage_id IS 'Identifier for the coverage.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.policy_id IS 'Policy the coverage is granted under.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.coverage_type_code IS 'Kind of cover granted. One source row becomes one or two coverage rows.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.limit_amount IS 'Maximum amount payable under this coverage, in the policy currency; empty where unlimited or not applicable. Third-party liability limit; applies to the MOTOR_TPL row.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.deductible_amount IS 'Amount borne by the insured before this coverage responds, in the policy currency. The policy system says ''excess''; applies to the MOTOR_OWN_DAMAGE row.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.sum_insured_amount IS 'Declared value insured under this coverage, in the policy currency. Not held by the policy system for motor; vehicle value is on the vehicle.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage.cover_code IS 'Policy-system cover code kept for reference: COMP comprehensive, TPFT third party fire and theft, TPO third party only.';

ALTER VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_coverage SET TAGS ('bxc_source_system' = 'PAS_MOTOR', 'bxc_concept' = 'coverage', 'bxc_mapping' = 'pas_motor', 'bxc_certification' = 'certified');

