ALTER TABLE lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_premium_txn ALTER COLUMN txn_amt COMMENT 'Maps to premium_transaction.amount: Signed amount of the movement in the transaction currency: written and positive adjustments positive, returns negative.';

ALTER TABLE lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_premium_txn ALTER COLUMN txn_amt SET TAGS ('bxc_concept' = 'premium_transaction.amount');

