ALTER TABLE lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_premium_txn ALTER COLUMN txn_type SET TAGS ('bxc_concept' = 'premium_transaction.source_system_code');

CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction
COMMENT 'Written premium as booked by the policy system. Grain: One row per premium transaction (new business in this extract). Conformed from PAS_MOTOR (lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_premium_txn) by mapping pas_motor; column names and definitions are the core concept premium_transaction. Owner Head of Motor Underwriting; certified.'
AS
SELECT
  concat('PAS_MOTOR:', txn_id) AS premium_transaction_id,
  concat('PAS_MOTOR:', contract_reference) AS policy_id,
  CASE txn_type WHEN 'NEW_BUSINESS' THEN 'WRITTEN' END AS premium_transaction_type_code,
  txn_amt AS amount,
  'GBP' AS currency_code,
  ipt_amt AS ipt_amount,
  txn_dt AS transaction_date,
  'PAS_MOTOR' AS source_system_code
FROM lr_serverless_aws_us_catalog.bricksurance_src_pas.pol_premium_txn;

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.premium_transaction_id IS 'Identifier for the premium transaction.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.policy_id IS 'Policy the premium movement belongs to.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.premium_transaction_type_code IS 'Kind of premium movement. The policy system distinguishes new business from renewals; both are WRITTEN premium in the core.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.amount IS 'Signed amount of the movement in the transaction currency: written and positive adjustments positive, returns negative.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.currency_code IS 'Currency of the amount.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.ipt_amount IS 'Insurance premium tax on the movement, in the transaction currency.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.transaction_date IS 'Date the movement was booked.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction.source_system_code IS 'System of record the movement originates from.';

ALTER VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_premium_transaction SET TAGS ('bxc_source_system' = 'PAS_MOTOR', 'bxc_concept' = 'premium_transaction', 'bxc_mapping' = 'pas_motor', 'bxc_certification' = 'certified');
